    private boolean inside(View child,View parent){for(View current=child;current!=null;current=current.getParent() instanceof View?(View)current.getParent():null)if(current==parent)return true;return false;}
    private void exportGrade(int grade)throws Exception{
        final int[] widths={1280,2048,2400,2400},heights={853,1365,1600,1600},qualities={80,85,92,95};
        ui(()->call(editor,"exportLocalWorkspace",Collections.singletonList(photos.get(0))));until(()->get(editor,"batchQuickSaveDialog") instanceof Dialog&&((Dialog)get(editor,"batchQuickSaveDialog")).isShowing(),"single grade sheet");settle();Dialog quick=(Dialog)get(editor,"batchQuickSaveDialog");View root=quick.getWindow().getDecorView();SeekBar slider=(SeekBar)findTag(root,"quick-save-quality");drag(slider,grade);
        TextView size=(TextView)findTag(root,"quick-save-output-size");check(size.getText().toString().equals(widths[grade]+" × "+heights[grade]+" px"),"summary-resolves-grade-size-"+grade);
        View confirm=findTag(root,"quick-save-confirm");ensureVisible(confirm);Rect bounds=new Rect();check(confirm.getGlobalVisibleRect(bounds)&&bounds.height()>=confirm.getHeight()-1,"save-action-scrolls-fully-into-view");ui(()->confirm.performClick());
        until(()->{Object state=call(batch,"state");List<?> items=(List<?>)get(state,"items");return !(Boolean)call(batch,"isActive")&&((Number)get(state,"completed")).intValue()==1&&!items.isEmpty()&&((Number)get(items.get(0),"quality")).intValue()==qualities[grade];},"actual grade encoding");Object state=call(batch,"state");Object saved=((List<?>)get(state,"results")).get(0);File file=(File)call(saved,"file");BitmapFactory.Options boundsOnly=new BitmapFactory.Options();boundsOnly.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),boundsOnly);
        check(boundsOnly.outWidth==widths[grade]&&boundsOnly.outHeight==heights[grade],"actual-JPEG-dimensions-grade-"+grade);check(((Number)get(((List<?>)get(state,"items")).get(0),"quality")).intValue()==qualities[grade],"actual-rendered-quality-grade-"+grade);
        until(()->activeHasText("关闭"),"export result");clickActiveText("关闭");settle();
    }
    private void exportAdvancedCopies()throws Exception{
        Map<File,String> sourceHashes=new LinkedHashMap<>();for(Object photo:photos){File original=(File)call(photo,"file");sourceHashes.put(original,(String)stat("album.PhotoEditStore","hashFile",original));}Set<Long> previous=phoneJpegs();
        for(int count:new int[]{1,3})for(int attempt=0;attempt<2;attempt++){
            List<Object> selection=new ArrayList<>(photos.subList(0,count));
            ui(()->call(editor,"exportLocalWorkspace",selection));until(()->get(editor,"batchQuickSaveDialog") instanceof Dialog&&((Dialog)get(editor,"batchQuickSaveDialog")).isShowing(),"copy quick sheet");Dialog quick=(Dialog)get(editor,"batchQuickSaveDialog");ui(()->findTag(quick.getWindow().getDecorView(),"quick-save-advanced").performClick());until(()->get(editor,"batchExportDialog") instanceof Dialog&&((Dialog)get(editor,"batchExportDialog")).isShowing(),"copy advanced page");Dialog advanced=(Dialog)get(editor,"batchExportDialog");check(findTag(advanced.getWindow().getDecorView(),"save-extra-copy")==null&&findTag(advanced.getWindow().getDecorView(),"export-save-mode")==null,"export-has-no-reuse-option");View save=findTag(advanced.getWindow().getDecorView(),"export-confirm");ensureVisible(save);check(save.isEnabled(),"new-copy-export-ready-without-existing-file-lookup");Set<Long> before=new HashSet<>(previous);ui(()->save.performClick());until(()->!(Boolean)call(batch,"isActive")&&phoneJpegs().size()==before.size()+selection.size(),"fresh published MediaStore copies");Set<Long> after=phoneJpegs();Set<Long> added=new HashSet<>(after);added.removeAll(before);check(added.size()==selection.size(),"repeated-export-adds-distinct-gallery-rows-count-"+count+"-attempt-"+attempt);
            for(long id:added){android.net.Uri uri=ContentUris.withAppendedId(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,id);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getTargetContext().getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}check(bounds.outWidth==2400&&bounds.outHeight==1600,"new-gallery-copy-has-complete-JPEG");}previous=after;until(()->activeHasText("关闭"),"copy completion");clickActiveText("关闭");settle();
        }
        for(Map.Entry<File,String> source:sourceHashes.entrySet())check(source.getValue().equals(stat("album.PhotoEditStore","hashFile",source.getKey())),"repeated-single-and-batch-exports-preserve-source-bytes");
    }
    private Set<Long> phoneJpegs(){Set<Long> result=new HashSet<>();try(android.database.Cursor rows=getTargetContext().getContentResolver().query(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},"mime_type=? AND is_pending=0 AND owner_package_name=?",new String[]{"image/jpeg","cc.huevia"},null)){if(rows!=null)while(rows.moveToNext())result.add(rows.getLong(0));}return result;}
    private void drag(SeekBar slider,int grade)throws Exception{
        ensureVisible(slider);int[] xy=new int[2];slider.getLocationOnScreen(xy);float left=xy[0]+slider.getPaddingLeft(),range=slider.getWidth()-slider.getPaddingLeft()-slider.getPaddingRight(),from=left+range*slider.getProgress()/3f,to=left+range*grade/3f,y=xy[1]+slider.getHeight()/2f;long down=SystemClock.uptimeMillis();
        sendMotion(down,down,MotionEvent.ACTION_DOWN,from,y);for(int i=1;i<=8;i++)sendMotion(down,down+i*16,MotionEvent.ACTION_MOVE,from+(to-from)*i/8,y);sendMotion(down,down+144,MotionEvent.ACTION_UP,to,y);settle();
    }
    private void sendMotion(long down,long now,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,now,action,x,y,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();}
    private void ensureVisible(View view)throws Exception{ui(()->view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true));settle();}
    private void makeFixtures()throws Exception{File dir=new File(getTargetContext().getFilesDir(),"pictures/camera-album");dir.mkdirs();Bitmap image;try(InputStream in=getContext().getAssets().open("astronaut.png")){image=BitmapFactory.decodeStream(in);}Bitmap photo=Bitmap.createScaledBitmap(image,2400,1600,true);image.recycle();for(int i=0;i<3;i++){File file=new File(dir,"QA143-"+UUID.randomUUID()+"__QA_PHOTO_"+i+".JPG");try(OutputStream out=new FileOutputStream(file)){photo.compress(Bitmap.CompressFormat.JPEG,95-i,out);}Constructor<?> c=cls("album.DownloadedPhoto").getDeclaredConstructor(File.class,String.class,String.class,String.class,long.class);c.setAccessible(true);photos.add(c.newInstance(file.getCanonicalFile(),"QA_PHOTO_"+i+".JPG","","",file.lastModified()));}photo.recycle();}
    private boolean activeHasText(String text){android.view.accessibility.AccessibilityNodeInfo active=getUiAutomation().getRootInActiveWindow();return active!=null&&!active.findAccessibilityNodeInfosByText(text).isEmpty();}
    private void clickActiveText(String text)throws Exception{android.view.accessibility.AccessibilityNodeInfo active=getUiAutomation().getRootInActiveWindow();if(active!=null)for(android.view.accessibility.AccessibilityNodeInfo node:active.findAccessibilityNodeInfosByText(text)){if(node.getText()!=null&&text.contentEquals(node.getText())){while(node!=null&&!node.isClickable())node=node.getParent();if(node!=null&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){settle();return;}}}throw new AssertionError("Missing "+text);}
    private View root(){return activity.getWindow().getDecorView();}private float density(){return activity.getResources().getDisplayMetrics().density;}
    private View findTag(View v,String tag){if(tag.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View hit=findTag(((ViewGroup)v).getChildAt(i),tag);if(hit!=null)return hit;}return null;}
    private void capture(String name)throws Exception{settle();Bitmap image=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(output,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    private interface Work{void run()throws Exception;}private interface Condition{boolean test()throws Exception;}
    private void settle()throws Exception{waitForIdleSync();SystemClock.sleep(220);}private void until(Condition test,String label)throws Exception{long end=SystemClock.uptimeMillis()+35000;while(SystemClock.uptimeMillis()<end){if(test.test())return;SystemClock.sleep(40);}throw new AssertionError("Timeout "+label);}
    private void check(boolean pass,String label)throws Exception{checks.put(new JSONObject().put("name",label).put("pass",pass));if(!pass)throw new AssertionError(label);}
    private void ui(Work work)throws Exception{AtomicReference<Throwable>error=new AtomicReference<>();runOnMainSync(()->{try{work.run();}catch(Throwable t){error.set(t);}});if(error.get()!=null)throw new RuntimeException(error.get());}
    private Class<?>cls(String name)throws Exception{return loader.loadClass("cc.huevia."+name);}private Field field(Class<?>type,String name)throws Exception{for(Class<?>c=type;c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    private Object get(Object target,String name)throws Exception{return field(target.getClass(),name).get(target);}private void set(Object target,String name,Object value)throws Exception{field(target.getClass(),name).set(target,value);}private Object call(Object target,String name,Object...args)throws Exception{return invoke(target.getClass(),target,name,args);}private Object stat(String type,String name,Object...args)throws Exception{return invoke(cls(type),null,name,args);}
    private Object invoke(Class<?>type,Object target,String name,Object[]args)throws Exception{for(Method method:type.getDeclaredMethods())if(method.getName().equals(name)&&method.getParameterCount()==args.length){method.setAccessible(true);try{return method.invoke(target,args);}catch(IllegalArgumentException mismatch){continue;}catch(InvocationTargetException error){throw new RuntimeException(error.getCause());}}throw new NoSuchMethodException(name);}
